.sc-tw :root{
  --obsidian-void: oklch(12% 0.01 240);
  --holo-cyan: oklch(65% 0.2 260);
  --photon-white: oklch(98% 0.01 240);
  --flare-leak: radial-gradient(circle at 50% 50%, oklch(65% 0.2 260 / 0.15), transparent 70%);
}.sc-tw{
  font-family: 'Inter', sans-serif;
  background-color: var(--obsidian-void);
  color: var(--photon-white);
  overflow-x: hidden;
  margin: 0;
  padding: 0;
  view-transition-name: root;
}.sc-tw ::view-transition-old(root),.sc-tw ::view-transition-new(root){
  animation-duration: 0.8s;
  animation-timing-function: cubic-bezier(0.22, 1, 0.36, 1);
}.sc-tw .kinetic-anchor{
  position: fixed;
  top: 10vh;
  right: -5vw;
  width: 70vw;
  height: 90vh;
  z-index: 0;
  mask-image: radial-gradient(ellipse at 50% 50%, black 20%, transparent 70%), polygon(15% 0%, 100% 10%, 85% 100%, 0% 90%);
  mask-composite: intersect;
  -webkit-mask-image: radial-gradient(ellipse at 50% 50%, black 20%, transparent 70%), polygon(15% 0%, 100% 10%, 85% 100%, 0% 90%);
  -webkit-mask-composite: source-in;
  transform-style: preserve-3d;
  animation: float 18s cubic-bezier(0.4, 0, 0.2, 1) infinite alternate;
  pointer-events: none;
  opacity: 0.95;
}.sc-tw .kinetic-anchor video{
  width: 100%;
  height: 100%;
  object-fit: cover;
  transform: scale(1.2);
}.sc-tw .lens-refraction{
  background: color-mix(in oklch, var(--photon-white) 4%, transparent);
  backdrop-filter: blur(40px) brightness(1.1);
  -webkit-backdrop-filter: blur(40px) brightness(1.1);
  box-shadow: 
    0 40px 100px -20px rgba(0, 0, 0, 0.8),
    inset 0 1px 1px 0 rgba(255, 255, 255, 0.15),
    inset 0 -1px 1px 0 rgba(255, 255, 255, 0.05);
  border-radius: 40px;
  border: 1px solid rgba(255, 255, 255, 0.05);
}.sc-tw .photon-glow{
  background: var(--holo-cyan);
  color: #fff;
  position: relative;
  transition: all 0.4s cubic-bezier(0.22, 1, 0.36, 1);
  box-shadow: 
    0 0 30px oklch(65% 0.2 260 / 0.3),
    inset 0 2px 4px rgba(255, 255, 255, 0.4);
  border: none;
  border-radius: 9999px;
}.sc-tw .photon-glow:hover{
  transform: translateY(-2px) scale(1.02);
  box-shadow: 
    0 0 50px oklch(65% 0.2 260 / 0.6),
    inset 0 2px 4px rgba(255, 255, 255, 0.6);
}.sc-tw .optical-flare{
  position: absolute;
  width: 150vw;
  height: 150vh;
  background: var(--flare-leak);
  top: -25vh;
  left: -25vw;
  z-index: -1;
  pointer-events: none;
  filter: blur(100px);
}

@keyframes float {0%{ transform: translateY(0) rotateX(2deg) rotateY(-2deg) scale(1); }100%{ transform: translateY(-40px) rotateX(-2deg) rotateY(3deg) scale(1.02); }
}

@keyframes atomic-assembly {from{
    opacity: 0;
    transform: translateY(80px) scale(0.95) rotateX(5deg);
    filter: blur(15px);
  }to{
    opacity: 1;
    transform: translateY(0) scale(1) rotateX(0deg);
    filter: blur(0);
  }
}.sc-tw .scroll-assembly{
  animation: atomic-assembly linear both;
  animation-timeline: view();
  animation-range: entry 10% cover 35%;
  transform-style: preserve-3d;
}.sc-tw h1,.sc-tw h2,.sc-tw h3{
  font-family: 'SF Pro Display', sans-serif;
  letter-spacing: -0.04em;
}.sc-tw .asymmetric-hub{
  display: grid;
  grid-template-columns: minmax(300px, 1fr) minmax(400px, 1.5fr);
  gap: 4rem;
  align-items: center;
}

@media (max-width: 1024px) {.sc-tw .asymmetric-hub{
    grid-template-columns: 1fr;
  }
